    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dep, uint w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(address(this).balance >= dep);
        c.SetMinSum(dep + 1); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeEth = address(c).balance;

        bool reverted;
        c.Collect(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted || (c.balances(address(this)) == beforeBal && address(c).balance == beforeEth));
    }

    receive() external payable {}
