import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 dep, uint256 w) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(dep + 1) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        uint beforeEth = address(c).balance;
        bool reverted;
        try c.Collect(w) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted || (c.balances(address(this)) == beforeBal && address(c).balance == beforeEth));
    }

    function testFuzz_run(uint256 dep, uint256 w) public {
        _run(dep, w);
    }

    receive() external payable {}
}
